//! Rendering the read maps to the source of `ferrobridge-hl7v2`'s
//! `map::generated` module.
//!
//! One file per structure map under `guide/` and `overrides/`, each holding
//! one `static`, an index per directory listing them in id order, the table
//! map headers in `table.rs`, and the shapes in `model.rs`. Every string is
//! written as a Rust literal by its `Debug` form, which escapes it. Every
//! file opens with the `@generated` banner.

use std::collections::BTreeMap;
use std::fmt::{self, Write};

use crate::v2maps::read::{Kind, Map, Row};

/// The shapes the maps are statics of.
const MODEL: &str = include_str!("../templates/v2maps_model.rs");

/// The licence lines of a file generated into a `BUSL-1.1` crate.
const SPDX: &str =
    "// SPDX-FileCopyrightText: Cadasto B.V.\n// SPDX-License-Identifier: BUSL-1.1\n";

/// What the tree is rendered from.
#[derive(Debug)]
pub struct Sources<'a> {
    /// The guide package, as `<name> <version>`.
    pub package: &'a str,
    /// The guide's maps, by id.
    pub guide: &'a BTreeMap<String, Map>,
    /// FerroBRIDGE's structure overrides, by id.
    pub overrides: &'a BTreeMap<String, Map>,
    /// FerroBRIDGE's value package maps, by id.
    pub values: &'a BTreeMap<String, Map>,
}

/// Renders the tree, by path relative to the `generated` directory.
///
/// # Errors
///
/// Returns [`fmt::Error`] when writing to a string fails, which `String`
/// never does.
pub fn render(sources: &Sources<'_>) -> Result<BTreeMap<String, String>, fmt::Error> {
    let banner = format!(
        "// @generated by fhir-codegen from {} and FerroBRIDGE's overrides and value package. DO NOT EDIT.\n// Change the emitter (tools/fhir-codegen) or its inputs and regenerate.\n{SPDX}",
        sources.package
    );
    let mut files = BTreeMap::new();
    let mut root = banner.clone();
    writeln!(
        root,
        "//! The structure maps of {}, FerroBRIDGE's overrides of them, and the\n//! headers of the table maps a terminology server answers.\n//!\n//! `guide` holds every message, segment and data type map of the guide,\n//! `overrides` every map FerroBRIDGE replaces or adds, and `table` the id,\n//! url and groups of every table map of the guide and of the value package.\n//! Every file is `@generated` by `fhir-codegen`; change the emitter or its\n//! inputs and regenerate, never the output.\n",
        sources.package
    )?;
    root.push_str("pub(crate) mod guide;\npub(crate) mod model;\npub(crate) mod overrides;\npub(crate) mod table;\n");
    files.insert(String::from("mod.rs"), root);
    files.insert(String::from("model.rs"), format!("{banner}{MODEL}"));
    for (directory, maps, what) in [
        ("guide", sources.guide, "the guide"),
        ("overrides", sources.overrides, "FerroBRIDGE's overrides"),
    ] {
        let structure: Vec<&Map> = maps
            .values()
            .filter(|map| map.kind != Kind::Table)
            .collect();
        let mut index = banner.clone();
        writeln!(index, "//! The structure maps of {what}, in id order.\n")?;
        index.push_str("use crate::map::generated::model::Declared;\n\n");
        for map in &structure {
            writeln!(index, "mod {};", module(&map.id))?;
        }
        writeln!(
            index,
            "\n/// Every structure map of {what}, in id order.\npub(crate) static MAPS: [&Declared; {}] = [",
            structure.len()
        )?;
        for map in &structure {
            writeln!(index, "    &{}::MAP,", module(&map.id))?;
        }
        index.push_str("];\n");
        files.insert(format!("{directory}/mod.rs"), index);
        for map in structure {
            files.insert(
                format!("{directory}/{}.rs", module(&map.id)),
                render_map(&banner, map)?,
            );
        }
    }
    let mut table = banner;
    table.push_str("//! The headers of the table maps, in id order.\n\nuse crate::map::generated::model::DeclaredTable;\n\n");
    for (name, maps, what) in [
        ("GUIDE", sources.guide, "the guide"),
        ("VALUES", sources.values, "FerroBRIDGE's value package"),
    ] {
        let tables: Vec<&Map> = maps
            .values()
            .filter(|map| map.kind == Kind::Table)
            .collect();
        writeln!(
            table,
            "/// Every table map of {what}, in id order.\npub(crate) static {name}: [DeclaredTable; {}] = [",
            tables.len()
        )?;
        for map in tables {
            write!(
                table,
                "    DeclaredTable {{ id: {:?}, url: {:?}, title: {}, groups: &[",
                map.id,
                map.url,
                optional(map.title.as_deref())
            )?;
            for group in &map.groups {
                write!(
                    table,
                    "({}, {}), ",
                    optional(group.source.as_deref()),
                    optional(group.target.as_deref())
                )?;
            }
            table.push_str("] },\n");
        }
        table.push_str("];\n\n");
    }
    files.insert(String::from("table.rs"), table);
    Ok(files)
}

/// Renders the file of one structure map.
fn render_map(banner: &str, map: &Map) -> Result<String, fmt::Error> {
    let mut text = String::from(banner);
    writeln!(
        text,
        "//! `ConceptMap/{}`, from `ConceptMap-{}.json`.\n",
        map.id, map.id
    )?;
    text.push_str("use crate::map::generated::model::{Declared, DeclaredRow};\n\n");
    writeln!(
        text,
        "/// The map.\npub(super) static MAP: Declared = Declared {{\n    id: {:?},\n    url: {:?},\n    title: {},\n    rows: &[",
        map.id,
        map.url,
        optional(map.title.as_deref())
    )?;
    for row in &map.rows {
        render_row(&mut text, row)?;
    }
    text.push_str("    ],\n};\n");
    Ok(text)
}

/// Renders one row.
fn render_row(text: &mut String, row: &Row) -> fmt::Result {
    write!(
        text,
        "        DeclaredRow {{ source: {:?}, source_type: {}, target: {}, target_type: {}, assignment: {}, mapped_via: {}, depends_on: &[",
        row.source,
        optional(row.source_type.as_deref()),
        optional(row.target.as_deref()),
        optional(row.target_type.as_deref()),
        optional(row.assignment.as_deref()),
        optional(row.mapped_via.as_deref()),
    )?;
    for (property, value) in &row.depends_on {
        write!(text, "({property:?}, {value:?}), ")?;
    }
    text.push_str("] },\n");
    Ok(())
}

/// An optional text as a Rust `Option<&str>` expression.
fn optional(text: Option<&str>) -> String {
    text.map_or_else(|| String::from("None"), |text| format!("Some({text:?})"))
}

/// The module name of a map id: `segment-pid-to-patient` gives
/// `segment_pid_to_patient`.
fn module(id: &str) -> String {
    id.replace(['-', '.'], "_")
}

#[cfg(test)]
mod tests {
    use super::{module, optional};

    #[test]
    fn a_map_id_names_its_module_and_a_text_its_literal() {
        assert_eq!(
            module("datatype-ei-placer-to-identifier"),
            "datatype_ei_placer_to_identifier"
        );
        assert_eq!(optional(Some("\"MR\"")), "Some(\"\\\"MR\\\"\")");
        assert_eq!(optional(None), "None");
    }
}
